using System.Text;

namespace Gojo.Experiments.QualitativeFrieze;

public static partial class EquivalenceRevisionExperiment
{
    private static string Html(string data) => """
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Useful assumptions, visible revisions · Gojo</title><style>
*{box-sizing:border-box}:root{--ink:#27454a;--muted:#637269;--paper:#fbf8ef;--edge:#d5d5c6}body{margin:0;background:#eeeee2;color:var(--ink);font:16px/1.6 system-ui,sans-serif}main{max-width:1600px;margin:auto;padding:40px 28px 70px}header{max-width:1100px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:#a96640}h1{font:clamp(34px,4vw,53px)/1.15 Georgia,serif;margin:12px 0 20px}h2{font:30px/1.2 Georgia,serif;margin:10px 0}h3{font-size:16px;line-height:1.4;margin:0 0 10px}p{margin:10px 0 16px}.lede{font-size:19px}.nav{display:flex;flex-wrap:wrap;gap:9px;margin:20px 0 30px}a{color:#246a70;text-underline-offset:3px}.nav a{border:1px solid var(--edge);border-radius:20px;padding:6px 13px;background:var(--paper);text-decoration:none;font-size:14px}.legend,.totals{background:#e1e6d9;border-left:3px solid #849465;padding:15px 20px;max-width:1130px;margin:25px 0}.case{margin:50px 0 65px;scroll-margin-top:20px}.case>p{max-width:1100px}.stages{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px}.stages.two{grid-template-columns:repeat(2,minmax(0,1fr))}.panel{min-width:0;background:var(--paper);border:1px solid var(--edge);padding:20px}.panel img{width:100%;height:auto;display:block}.picture{display:block}.no-output{min-height:190px;display:grid;place-items:center;text-align:center;border:1px dashed #b5b5a4;background:#f0eee3;padding:20px}.status{font-size:14px;line-height:1.5;padding:9px 11px;background:#e7eddf;border-left:3px solid #638068;margin:12px 0}.status.conflict{border-color:#a45c6d;background:#f0e2e5}.status.blocked{border-color:#b9803f;background:#f1e6d5}.support{font-size:13px;color:var(--muted)}dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:16px 0;border-top:1px solid var(--edge);padding-top:13px}dt{font-size:12px;line-height:1.4;color:var(--muted)}dd{font-size:21px;margin:3px 0}.scope{font-size:13px;border-left:2px solid #a8ae96;padding:7px 11px;background:#f0efe5}.values{font-size:13px;margin:10px 0}.values li{margin:3px 0}.values code{color:#7c5338;font-size:13px}.publication{border-top:1px solid var(--edge);padding-top:10px;margin:13px 0}.publication.outside{border-left:3px solid #b88554;padding-left:12px}.publication h4{font-size:13px;margin:0}.publication p{margin:3px 0}.message{padding:13px 17px;background:#e9e4d6;font-size:14px;border-left:3px solid #bd9460}details{border-top:1px solid var(--edge);padding:13px 0;margin-top:15px}summary{cursor:pointer;font-size:14px}.table-wrap{overflow-x:auto;margin:15px 0}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;border-bottom:1px solid var(--edge);padding:9px;vertical-align:top}th{font-weight:650}.candidate-row.chosen{background:#e6eddf}.tag{font-size:12px;color:#66745b}.footer{font-size:14px;color:var(--muted);border-top:1px solid var(--edge);padding-top:20px}@media(max-width:1050px){.stages,.stages.two{grid-template-columns:1fr}.panel img{max-height:290px;object-fit:contain}.no-output{min-height:150px}main{padding:25px 16px}.nav{gap:7px}.nav a{font-size:13px}}
</style></head><body><main><header><span class="eyebrow">Gojo · provisional equivalence and local revision</span><h1>A useful guess can change.<br>Its useful structure can remain.</h1><p class="lede">Four small cases separate observed structure, shared-parameter assumptions, concrete receiver output and the context that selects a working interpretation.</p><p>A square-like completion may be reasonable while spans are unspecified. Later unequal participation can select a rectangle-like completion while the earlier coarse closed-contour read stays supported. Conflicting reports and blocked detail remain visible.</p><nav class="nav"><a href="overview.html">All stages together</a><a href="diagnostics.json">Captured read summaries</a><a href="equivalence.gojo.json.gz">Native evidence archive</a><a href="../communication-loop/gallery.html">Earlier communication loop</a></nav></header><div class="legend"><strong>Three different claims:</strong> the output has a closed four-edge route; some source roles are provisionally represented by one shared parameter; a separately published source comparison agrees or disagrees with that sharing.<p>Words such as <code>u · u</code> denote repeated participation in one declared unmeasured basis. Screen angles and illustrative lengths are presentation choices. The reader does not infer Euclidean square geometry from the picture.</p></div><div class="totals" id="totals"></div><div id="cases"></div><details><summary>Scope and limitations of this run</summary><ul id="limits"></ul></details><footer class="footer"><p id="native-summary"></p><p>The engine evaluates finite authored candidates. This run exercises selection, execution, independent reading and revision; active question learning is a later step.</p></footer><script id="data" type="application/json">__DATA__</script><script>
'use strict';const model=JSON.parse(document.querySelector('#data').textContent),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const valueList=values=>`<ul class="values">${values.map(v=>`<li>${esc(v.role)}: <code>${esc(v.word)}</code></li>`).join('')}</ul>`;
const metric=(name,value)=>`<div><dt>${esc(name)}</dt><dd>${esc(value)}</dd></div>`;
function status(stage){if(stage.lowerResolution)return ['blocked','Coarse answer only · finer request remains blocked'];if(stage.conflicts)return ['conflict',stage.image?'Working interpretation · source conflict remains':'Conflicting evidence · no unqualified output'];if(!stage.image)return ['blocked','No admissible executable output'];return ['',stage.withdrawn?'Revised completion · coarse contour preserved':'Provisional completion · source equality is a separate question']}
for(const item of model.cases){const card=document.createElement('article');card.className='case';card.id=item.id;card.dataset.case=item.id;card.innerHTML=`<span class="eyebrow">${esc(item.id)} · inspectable experiment</span><h2>${esc(item.name)}</h2><p>${esc(item.description)}</p><div class="stages ${item.stages.length===2?'two':''}"></div><p class="message">${item.id==='E01'?'The next transmission supplies the distinguishing native span publication immediately. It avoids making and repairing the same equal-span guess.':'The captured correction keeps the actual distinguishing publication and its source context available for later communication.'}</p>`;
for(const stage of item.stages){const panel=document.createElement('section');panel.className='panel';panel.dataset.stage=stage.id;panel.dataset.output=stage.image?'yes':'no';panel.dataset.lowerResolution=String(stage.lowerResolution);const state=status(stage);panel.innerHTML=`<span class="eyebrow">${esc(stage.id)}</span><h3>${esc(stage.name)}</h3>${stage.image?`<a class="picture" href="${stage.image}"><img src="${stage.image}" alt="${esc(stage.chosen)}"></a>`:'<div class="no-output">No candidate meets the selected evidence and capability contract.</div>'}<p class="status ${state[0]}">${esc(state[1])}</p><p>${esc(stage.description)}</p><p class="scope"><strong>Working read:</strong> ${esc(stage.workingScope)}</p><dl>${metric('Supported coarse contour',stage.image?(stage.coarseClosed?'Yes':'Open'):'Not executed')+metric('Actual closed routes',stage.image?stage.cycles:'—')+metric('Eligible / nondominated candidates',stage.eligible+' / '+stage.pareto)+metric('Conflict witnesses',stage.conflicts)+metric('Prior assumptions carried',stage.carried)+metric('Prior assumptions withdrawn',stage.withdrawn)}</dl><h3>Published source evidence</h3><div class="publications">${stage.publications.length?stage.publications.map(p=>`<div class="publication ${p.working?'':'outside'}"><h4>${esc(p.source)} · ${esc(p.revision)}</h4><p class="support">${p.working?'Included in working read':'Retained outside this selected read'}</p>${valueList(p.values)}</div>`).join(''):'<p class="support">No source span values are published. The coarse contour and provisional completion do not certify source span equality.</p>'}</div><h3>Read from fresh output</h3>${stage.image?valueList(stage.sampleValues):'<p class="support">No output sample was produced.</p>'}`;card.querySelector('.stages').append(panel)}
card.insertAdjacentHTML('beforeend',`<details class="candidates"><summary>Compare every candidate, its assumptions and sample conformance</summary>${item.stages.map(stage=>`<h3>${esc(stage.name)}</h3><div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Parameters / native program cost</th><th>Source equality evidence support / refute / open</th><th>Candidate sample mismatches all / working</th><th>Blocked / conflict witnesses</th><th>Admitted?</th></tr></thead><tbody>${stage.candidates.map(c=>`<tr class="candidate-row ${c.chosen?'chosen':''}"><td>${esc(c.name)}${c.chosen?'<br><strong>Selected</strong>':''}${c.pareto?'<br><span class="tag">Nondominated</span>':''}</td><td>${c.parameters} / ${c.nativeCost}</td><td>${c.supported} / ${c.refuted} / ${c.open}<br><span class="tag">Working refutations: ${c.workingRefuted}</span></td><td>${c.sampleRefuted} / ${c.workingSampleRefuted}</td><td>${c.blocked} / ${c.conflicts}</td><td>${c.eligible?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div>`).join('')}</details>`);document.querySelector('#cases').append(card)}
document.querySelector('#totals').textContent=`${model.cases.length} cases · ${model.stages} captured stages · ${model.cases.flatMap(c=>c.stages).filter(s=>s.image).length} fresh acknowledged output executions. All source and sample comparisons precede rendering.`;
document.querySelector('#limits').innerHTML=model.limits.map(s=>`<li>${esc(s)}</li>`).join('');document.querySelector('#native-summary').textContent=`${model.nativeElements.toLocaleString()} captured native participants · ${model.nativeNumericElements} numeric participants · archive restoration verified.`;
const requested=new URLSearchParams(location.search).get('case');if(requested)document.getElementById(requested)?.scrollIntoView();
</script></main></body></html>
""".Replace("__DATA__", data);

    private static string Overview(IReadOnlyList<CaseModel> cases)
    {
        var html = new StringBuilder("<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Equivalence and revision · all stages</title><style>*{box-sizing:border-box}body{margin:0;background:#eeeee2;color:#27454a;font:15px/1.6 system-ui}main{max-width:1550px;margin:auto;padding:30px}h1,h2{font-family:Georgia,serif;font-weight:400}h1{font-size:38px}.row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.row.two{grid-template-columns:repeat(2,minmax(0,1fr))}figure{background:#fbf8ef;border:1px solid #d7d6c7;padding:15px;margin:0}img{width:100%;height:auto}.none{height:180px;display:grid;place-items:center;background:#f0eee3;border:1px dashed #b5b5a4}a{color:#246a70}article{margin:35px 0 45px}figcaption{font-size:14px}.warning{color:#9e5d42}@media(max-width:900px){main{padding:20px 15px}.row,.row.two{grid-template-columns:1fr}}</style></head><body><main><h1>Provisional equivalence · visible revisions</h1><p><a href='gallery.html'>Full evidence and candidate comparisons</a> · <a href='diagnostics.json'>Captured summaries</a></p><p>Square-like and rectangular drawings illustrate a declared unmeasured participation basis. An earlier supported coarse contour can survive withdrawal of a finer equality assumption. All pictures show fresh native output after analysis.</p>");
        foreach (var item in cases)
        {
            html.Append($"<article><h2><a href='gallery.html?case={item.Id}'>{H(item.Id + " · " + item.Name)}</a></h2><p>{H(item.Description)}</p><div class='row {(item.Stages.Length == 2 ? "two" : "") }'>");
            foreach (var stage in item.Stages)
            {
                var status = stage.LowerResolution ? "Coarse output; finer request blocked" : stage.Conflicts > 0 ? "Conflicting source evidence remains" : stage.Image is null ? "No admissible output" : "Coarse contour supported";
                html.Append($"<figure><h3>{H(stage.Name)}</h3>{(stage.Image is null ? "<div class='none'>No admissible output</div>" : $"<img src='{stage.Image}' alt='{H(stage.Chosen ?? stage.Name)}'>")}<figcaption><strong>{H(stage.Id)}</strong> · {H(status)}<br>{stage.Carried} assumptions carried · {stage.Withdrawn} withdrawn<br>{H(stage.WorkingScope)}<p>{H(stage.Description)}</p></figcaption></figure>");
            }
            html.Append("</div></article>");
        }
        return html.Append("<p><a href='gallery.html'>Inspect source evidence and all candidates</a> · <a href='equivalence.gojo.json.gz'>Native evidence archive</a></p></main></body></html>").ToString();
    }
}
